(function(){
  'use strict';
  const KEY='safariPocketbookLanguageNotes';
  const prompts=['Hello','Thank you','Please','Where is…?','I need help','Call an ambulance'];
  const pack=(code,source,phrases)=>({code,source,phrases});
  const PHRASEBOOKS={
    English:pack('en','https://en.wikivoyage.org/wiki/English_phrasebook',[
      ['greeting','Hello','Hello','heh-LOH'],['greeting','Good morning','Good morning','good MOR-ning'],['courtesy','Thank you','Thank you','THANGK yoo'],['courtesy','Please','Please','pleez'],['courtesy','Excuse me / sorry','Excuse me / Sorry','ek-SKYOOZ mee / SOR-ee'],['essential','Yes','Yes','yes'],['essential','No','No','noh'],['essential','I do not understand','I do not understand','eye doo not un-der-STAND'],['essential','Do you speak English?','Do you speak English?','doo yoo speak ING-glish'],['direction','Where is …?','Where is …?','wair iz'],['safety','I need help','I need help','eye need help'],['safety','Call the police','Call the police','kawl thuh puh-LEES'],['safety','Call an ambulance','Call an ambulance','kawl an AM-byuh-lans']
    ]),
    Tswana:pack('tn','https://en.wikivoyage.org/wiki/Tswana_phrasebook',[
      ['greeting','Hello','Dumela','doo-MEH-lah'],['greeting','Good morning','Dumela, o tsogile jang?','doo-MEH-lah, oo tsoh-GEE-leh jahng'],['courtesy','Thank you','Ke a leboga','keh ah leh-BOH-gah'],['courtesy','Please','Tsweetswee','tsweh-tsweh'],['courtesy','Excuse me / sorry','Intshwarele','in-tshwa-REH-leh'],['essential','Yes','Ee','eh'],['essential','No','Nnyaa','nyah'],['essential','I do not understand','Ga ke tlhaloganye','hah keh tla-loh-GAH-nyeh'],['essential','Do you speak English?','A o bua Sekgoa?','ah oo boo-ah seh-KHO-ah'],['direction','Where is …?','… e kae?','eh kai'],['safety','I need help','Ke kopa thuso','keh KOH-pah too-soh'],['safety','Call the police','Bitsa mapodise','BEET-sah mah-poh-DEE-seh'],['safety','Call an ambulance','Bitsa ambulense','BEET-sah am-boo-LEN-seh']
    ]),
    Swahili:pack('sw','https://en.wikivoyage.org/wiki/Swahili_phrasebook',[
      ['greeting','Hello','Jambo','JAHM-boh'],['greeting','Good morning','Habari za asubuhi','hah-BAH-ree zah ah-soo-BOO-hee'],['courtesy','Thank you','Asante','ah-SAHN-teh'],['courtesy','Please','Tafadhali','tah-fah-DHAH-lee'],['courtesy','Excuse me / sorry','Samahani','sah-mah-HAH-nee'],['essential','Yes','Ndiyo','n-DEE-yoh'],['essential','No','Hapana','hah-PAH-nah'],['essential','I do not understand','Sielewi','see-eh-LEH-wee'],['essential','Do you speak English?','Unazungumza Kiingereza?','oo-nah-zoong-GOOM-zah kee-eeng-geh-REH-zah'],['direction','Where is …?','… iko wapi?','ee-koh WAH-pee'],['safety','I need help','Nahitaji msaada','nah-hee-TAH-jee m-sah-AH-dah'],['safety','Call the police','Ita polisi','EE-tah poh-LEE-see'],['safety','Call an ambulance','Ita ambulansi','EE-tah am-boo-LAHN-see']
    ]),
    French:pack('fr','https://en.wikivoyage.org/wiki/French_phrasebook',[
      ['greeting','Hello','Bonjour','bohn-ZHOOR'],['greeting','Good morning','Bonjour','bohn-ZHOOR'],['courtesy','Thank you','Merci','mehr-SEE'],['courtesy','Please','S’il vous plaît','seel voo PLEH'],['courtesy','Excuse me / sorry','Excusez-moi / Pardon','ex-kew-zay MWAH / par-DOHN'],['essential','Yes','Oui','wee'],['essential','No','Non','nohn'],['essential','I do not understand','Je ne comprends pas','zhuh nuh kohn-PRAHN pah'],['essential','Do you speak English?','Parlez-vous anglais ?','par-lay VOO ahn-GLEH'],['direction','Where is …?','Où est … ?','oo EH'],['safety','I need help','J’ai besoin d’aide','zhay buh-ZWAN ded'],['safety','Call the police','Appelez la police','ah-play lah poh-LEES'],['safety','Call an ambulance','Appelez une ambulance','ah-play ewn ahn-bew-LAHNS']
    ]),
    Portuguese:pack('pt','https://en.wikivoyage.org/wiki/Portuguese_phrasebook',[
      ['greeting','Hello','Olá','oh-LAH'],['greeting','Good morning','Bom dia','bohm DEE-ah'],['courtesy','Thank you','Obrigado / Obrigada','oh-bree-GAH-doo / oh-bree-GAH-dah'],['courtesy','Please','Por favor','poor fah-VOR'],['courtesy','Excuse me / sorry','Desculpe','desh-KOOL-peh'],['essential','Yes','Sim','seeng'],['essential','No','Não','nowng'],['essential','I do not understand','Não compreendo','nowng kohm-preh-EN-doo'],['essential','Do you speak English?','Fala inglês?','FAH-lah een-GLESH'],['direction','Where is …?','Onde fica …?','ON-deh FEE-kah'],['safety','I need help','Preciso de ajuda','preh-SEE-zoo deh ah-ZHOO-dah'],['safety','Call the police','Chame a polícia','SHAH-meh ah poh-LEE-see-ah'],['safety','Call an ambulance','Chame uma ambulância','SHAH-meh OO-mah ahm-boo-LAHN-see-ah']
    ]),
    Arabic:pack('ar','https://en.wikivoyage.org/wiki/Arabic_phrasebook',[
      ['greeting','Hello','مرحبا','mar-ha-ban'],['greeting','Good morning','صباح الخير','sa-BAAH al-khayr'],['courtesy','Thank you','شكرا','SHUK-ran'],['courtesy','Please','من فضلك','min FAD-lak'],['courtesy','Excuse me / sorry','عذرا','UZ-ran'],['essential','Yes','نعم','na-am'],['essential','No','لا','laa'],['essential','I do not understand','لا أفهم','laa AF-ham'],['essential','Do you speak English?','هل تتحدث الإنجليزية؟','hal ta-ta-KAL-lam al-in-glee-ZEE-yah'],['direction','Where is …?','أين …؟','AY-na'],['safety','I need help','أحتاج إلى مساعدة','ah-TAAJ ee-laa moo-SAA-ah-dah'],['safety','Call the police','اتصل بالشرطة','it-ta-SIL bish-SHUR-tah'],['safety','Call an ambulance','اتصل بالإسعاف','it-ta-SIL bil-is-AAF']
    ]),
    Amharic:pack('am','https://en.wikivoyage.org/wiki/Amharic_phrasebook',[
      ['greeting','Hello','ሰላም','seh-LAHM'],['greeting','Good morning','እንደምን አደሩ?','in-deh-MIN ah-deh-ROO'],['courtesy','Thank you','አመሰግናለሁ','ah-meh-seh-gee-NAH-leh-hoo'],['courtesy','Please','እባክዎ','ih-BAH-kwo'],['courtesy','Excuse me / sorry','ይቅርታ','yih-KIR-tah'],['essential','Yes','አዎ','ah-WOH'],['essential','No','አይ','eye'],['essential','I do not understand','አልገባኝም','ahl-geh-BAH-nyim'],['essential','Do you speak English?','እንግሊዝኛ ይናገራሉ?','in-glee-ZIN-yah yee-nah-geh-RAH-loo'],['direction','Where is …?','… የት ነው?','yet new'],['safety','I need help','እርዳታ እፈልጋለሁ','ir-DAH-tah ih-feh-lee-GAH-leh-hoo'],['safety','Call the police','ፖሊስ ይጥሩ','poh-LEES yee-TIR-roo'],['safety','Call an ambulance','አምቡላንስ ይጥሩ','am-boo-LAHNS yee-TIR-roo']
    ])
  };
  const LANGUAGE_ALIASES={Hassaniya:'Arabic'};
  const PACK_PRIORITY=['Tswana','Swahili','Amharic','Arabic','Portuguese','French','English'];
  window.pocketbookPhrasebooks=PHRASEBOOKS;
  window.pocketbookPhraseAliases=LANGUAGE_ALIASES;
  const safe=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch(error){return{}}}
  function countryKey(country){return country.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-')}
  function availableLanguages(items){const seen=new Set();return items.map(language=>LANGUAGE_ALIASES[language]||language).filter(language=>PHRASEBOOKS[language]&&!seen.has(language)&&seen.add(language)).sort((a,b)=>PACK_PRIORITY.indexOf(a)-PACK_PRIORITY.indexOf(b))}
  function phraseRows(language,query='',category='all'){
    const phrasebook=PHRASEBOOKS[language];if(!phrasebook)return'';const needle=query.trim().toLocaleLowerCase();
    return phrasebook.phrases.map((entry,index)=>({entry,index})).filter(({entry:[group,meaning,phrase]})=>(category==='all'||group===category)&&(!needle||`${meaning} ${phrase}`.toLocaleLowerCase().includes(needle))).map(({entry:[group,meaning,phrase,pronunciation],index})=>`<article class="phrase-card" data-phrase-group="${group}"><div><small>${safe(meaning)}</small><strong lang="${phrasebook.code}">${safe(phrase)}</strong><span>${safe(pronunciation)}</span></div><button type="button" data-speak-common="${index}" aria-label="Hear device pronunciation of ${safe(phrase)}">▶</button></article>`).join('');
  }
  window.countryLanguageHtml=function(country,languages){
    const notes=read()[countryKey(country)]||{},items=Object.values(languages||{}),available=availableLanguages(items),selected=available[0]||'English',chips=items.length?items.map(language=>`<span>${safe(language)}</span>`).join(''):'<span>Language reference unavailable offline</span>';
    return `<section class="entry-section language-section" data-language-country="${safe(country)}"><div class="entry-kicker">LANGUAGES &amp; LOCAL ETIQUETTE</div><h3>Speak with confidence</h3><div class="country-languages">${chips}</div><p class="language-source">Country-language reference: bundled mledoze/countries snapshot dated 9 Sep 2026. Language use and preferred greetings vary by place and community.</p><details class="common-phrasebook" open><summary><span>Common phrases</span><small>Available offline</small></summary><div class="phrasebook-tools"><label>Phrase language<select data-phrase-language>${available.map(language=>`<option value="${safe(language)}">${safe(language)}</option>`).join('')||'<option value="English">English</option>'}</select></label><label class="phrase-search"><span>Search phrases</span><input type="search" data-phrase-search placeholder="Try help, thank you or where" autocomplete="off"></label><div class="phrase-categories" role="group" aria-label="Phrase categories"><button type="button" class="active" data-phrase-category="all">All</button><button type="button" data-phrase-category="greeting">Greetings</button><button type="button" data-phrase-category="courtesy">Courtesy</button><button type="button" data-phrase-category="essential">Essentials</button><button type="button" data-phrase-category="direction">Directions</button><button type="button" data-phrase-category="safety">Safety</button></div></div><div class="phrase-results" aria-live="polite">${phraseRows(selected)}</div><p class="phrase-empty" hidden>No matching phrase. Try another word or category.</p><div class="phrasebook-source">Starter travel phrases · <a data-phrase-source href="${PHRASEBOOKS[selected].source}" target="_blank" rel="noopener">Review phrasebook source ↗</a><small>Pronunciation spellings are approximate. The play button uses a device-generated voice, not a native-speaker recording. Confirm dialect and emergency terminology locally.</small></div></details><div class="phrase-notebook"><strong>Your locally verified phrase notes</strong><p>Add translations confirmed by a guide, host or fluent speaker. They remain on this device.</p>${prompts.map((prompt,index)=>`<label><span>${safe(prompt)}</span><input data-phrase-index="${index}" value="${safe(notes[index]||'')}" placeholder="Add a locally verified translation"><button type="button" data-speak-phrase="${index}" aria-label="Pronounce saved translation for ${safe(prompt)}">▶</button></label>`).join('')}<button type="button" class="save-phrases">Save phrase notes</button><small class="voice-disclosure">Pronunciation uses an available device-generated voice. It is not represented as a native-speaker recording.</small></div></section>`
  };
  window.mountCountryLanguage=function(country){
    const section=document.querySelector(`[data-language-country="${CSS.escape(country)}"]`);if(!section)return;const key=countryKey(country),select=section.querySelector('[data-phrase-language]'),search=section.querySelector('[data-phrase-search]'),results=section.querySelector('.phrase-results'),empty=section.querySelector('.phrase-empty'),source=section.querySelector('[data-phrase-source]');let category='all';
    const render=()=>{const language=select.value,html=phraseRows(language,search.value,category);results.innerHTML=html;empty.hidden=!!html;source.href=PHRASEBOOKS[language].source};
    select.addEventListener('change',render);search.addEventListener('input',render);section.querySelector('.phrase-categories').addEventListener('click',event=>{const button=event.target.closest('[data-phrase-category]');if(!button)return;category=button.dataset.phraseCategory;section.querySelectorAll('[data-phrase-category]').forEach(item=>item.classList.toggle('active',item===button));render()});
    section.querySelector('.save-phrases').addEventListener('click',()=>{const all=read();all[key]={};section.querySelectorAll('[data-phrase-index]').forEach(input=>{if(input.value.trim())all[key][input.dataset.phraseIndex]=input.value.trim()});localStorage.setItem(KEY,JSON.stringify(all));const toast=document.getElementById('toast');toast.textContent=`${country} phrase notes saved on this device.`;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)});
    section.addEventListener('click',event=>{const common=event.target.closest('[data-speak-common]'),personal=event.target.closest('[data-speak-phrase]');let value='',lang='';if(common){const entry=PHRASEBOOKS[select.value].phrases[Number(common.dataset.speakCommon)];value=entry?.[2]||'';lang=PHRASEBOOKS[select.value].code}else if(personal)value=section.querySelector(`[data-phrase-index="${personal.dataset.speakPhrase}"]`).value.trim();if(!value)return;window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(value);if(lang)utterance.lang=lang;window.speechSynthesis.speak(utterance)})
  };
})();
